App.my.m = () => App.load('match', null);
App.my.setM = (m) => App.save('match', m);
App.my.inn = (m, k) => {
  const balls = ((m.inn || [])[k] || { balls: [] }).balls;
  let runs = 0, wk = 0, legal = 0, extras = 0;
  for (const b of balls) {
    runs += (Number(b.r) || 0) + (b.x ? 1 : 0);
    if (b.x) extras++;
    if (b.w) wk++;
    if (!b.x) legal++;
  }
  return { runs, wk, legal, extras, balls };
};
App.my.ov = (legal) => Math.floor(legal / 6) + '.' + (legal % 6);
App.my.maxW = (m) => Math.max(1, (Number(m.players) || 11) - 1);
App.my.bat = (m, k) => (k === 0 ? m.first : m.first === m.a ? m.b : m.a);
App.my.innDone = (m, k) => {
  const s = App.my.inn(m, k);
  if (s.legal >= m.overs * 6 || s.wk >= App.my.maxW(m)) return true;
  return k === 1 && s.runs > App.my.inn(m, 0).runs;
};
App.my.result = (m) => {
  const a = App.my.inn(m, 0), b = App.my.inn(m, 1);
  if (b.runs > a.runs) return App.my.bat(m, 1) + ' ' + (App.my.maxW(m) - b.wk) + ' వికెట్ల తేడాతో గెలిచింది';
  if (b.runs === a.runs) return 'టై! రెండు జట్లూ సమానం';
  return App.my.bat(m, 0) + ' ' + (a.runs - b.runs) + ' పరుగుల తేడాతో గెలిచింది';
};
App.my.innLine = (m, k) => { const s = App.my.inn(m, k); return App.my.bat(m, k) + ' ' + s.runs + '/' + s.wk + ' (' + App.my.ov(s.legal) + ' ఓవర్లు)'; };
App.my.line = (m) => {
  const k = m.cur, s = App.my.inn(m, k);
  let t = App.my.innLine(m, k);
  if (k === 1 && !m.done) { const need = App.my.inn(m, 0).runs + 1 - s.runs; t += '. ఇంకా ' + Math.max(0, need) + ' పరుగులు, ' + (m.overs * 6 - s.legal) + ' బంతుల్లో'; }
  if (m.done) t += '. ' + App.my.result(m);
  return t;
};
App.my.full = (m) => [App.my.innLine(m, 0)].concat(m.cur === 1 || m.done ? [App.my.innLine(m, 1)] : []).concat(m.done ? ['🏆 ' + App.my.result(m)] : []).join('\n');

App.onShow('home', () => {
  App.awake(false).catch(() => {});
  const m = App.my.m(), on = !!(m && !m.done);
  App.show('#home-on', on);
  if (on) App.text('#home-on-line', App.my.line(m));
  if (!App.val('#home-a')) App.val('#home-a', App.load('lastA', 'జట్టు A'));
  if (!App.val('#home-b')) App.val('#home-b', App.load('lastB', 'జట్టు B'));
  if (!App.val('#home-overs')) App.val('#home-overs', App.load('lastOvers', 6));
  if (!App.val('#home-players')) App.val('#home-players', App.load('lastPlayers', 11));
});
App.click('#home-continue', () => App.go('score'));
App.click('#home-start', async () => {
  const a = App.val('#home-a').slice(0, 30) || 'జట్టు A';
  let b = App.val('#home-b').slice(0, 30) || 'జట్టు B';
  if (a === b) b = b + ' 2';
  const overs = Math.round(Number(App.val('#home-overs'))), players = Math.round(Number(App.val('#home-players')));
  if (!(overs >= 1 && overs <= 50)) { App.toast('ఓవర్లు 1 నుంచి 50 లోపు రాయండి'); return; }
  if (!(players >= 2 && players <= 15)) { App.toast('ఆటగాళ్లు 2 నుంచి 15 లోపు రాయండి'); return; }
  const old = App.my.m();
  if (old && !old.done && !(await App.ask('జరుగుతున్న మ్యాచ్ వదిలేసి కొత్తది మొదలుపెట్టాలా?', 'కొత్తది', 'వద్దు'))) return;
  App.save('lastA', a); App.save('lastB', b); App.save('lastOvers', overs); App.save('lastPlayers', players);
  App.my.setM({ id: App.uid(), a, b, overs, players, first: App.val('#home-first') === 'b' ? b : a, inn: [{ balls: [] }, { balls: [] }], cur: 0, done: false, date: App.today() });
  App.beep('ok');
  App.go('score');
});

