App.my.ballText = (b) => (b.w ? 'W' : b.x === 'wd' ? 'వై' + (b.r ? '+' + b.r : '') : b.x === 'nb' ? 'నో' + (b.r ? '+' + b.r : '') : String(b.r));
App.my.thisOver = (balls) => {
  const groups = [[]];
  let legal = 0;
  for (const b of balls) { groups[groups.length - 1].push(b); if (!b.x) { legal++; if (legal % 6 === 0) groups.push([]); } }
  const last = groups[groups.length - 1];
  return last.length || groups.length < 2 ? last : groups[groups.length - 2];
};
App.onShow('score', () => {
  const m = App.my.m();
  App.show('#sc-none', !m);
  App.show('#sc-main', !!m);
  if (!m) { App.title('స్కోర్'); return; }
  App.awake(!m.done).catch(() => {});
  const k = m.cur, s = App.my.inn(m, k);
  App.title(m.a + ' vs ' + m.b);
  App.text('#sc-team', App.my.bat(m, k) + (k === 0 ? ' బ్యాటింగ్' : ' బ్యాటింగ్ (2వ ఇన్నింగ్స్)'));
  App.text('#sc-runs', s.runs + '/' + s.wk);
  App.text('#sc-overs', App.my.ov(s.legal) + ' / ' + m.overs + ' ఓవర్లు' + (s.legal ? ' · రన్ రేట్ ' + App.n(s.runs * 6 / s.legal, 2) : '') + (s.extras ? ' · ఎక్స్‌ట్రాలు ' + s.extras : ''));
  const target = App.my.inn(m, 0).runs + 1;
  App.text('#sc-need', m.done ? '' : k === 1 ? 'టార్గెట్ ' + target + ' · ఇంకా ' + Math.max(0, target - s.runs) + ' పరుగులు, ' + (m.overs * 6 - s.legal) + ' బంతుల్లో' : '');
  const over = App.my.thisOver(s.balls);
  App.set('#sc-over', over.length ? over.map((b) => `<span class="chip${b.w ? ' on' : ''}">${App.esc(App.my.ballText(b))}</span>`).join('') : '<span class="faint">ఇంకా బంతి వేయలేదు</span>');
  App.show('#sc-pad', !m.done);
  App.show('#sc-done', !!m.done);
  if (m.done) App.text('#sc-result', '🏆 ' + App.my.result(m));
});
App.my.ball = async (b) => {
  const m = App.my.m();
  if (!m || m.done) return;
  m.inn[m.cur].balls.push(b);
  let say = '';
  if (App.my.innDone(m, m.cur)) {
    if (m.cur === 0) { m.cur = 1; say = 'ఇన్నింగ్స్ అయిపోయింది. ' + App.my.bat(m, 1) + ' టార్గెట్ ' + (App.my.inn(m, 0).runs + 1); }
    else {
      m.done = true;
      say = App.my.result(m);
      App.add('history', { mid: m.id, date: m.date, a: m.a, b: m.b, overs: m.overs, line1: App.my.innLine(m, 0), line2: App.my.innLine(m, 1), result: say });
    }
  }
  App.my.setM(m);
  App.beep(b.w ? 'err' : b.r === 4 || b.r === 6 ? 'done' : 'tap');
  App.refresh();
  if (say) { App.toast(say, 4); try { await App.say(say); } catch (e) { /* the toast says it too */ } }
};
App.click('#sc-pad .run', async (ev, el) => {
  if (el.dataset.w) return App.my.ball({ r: 0, w: true, x: '' });
  if (el.dataset.x) {
    const i = await App.pick(el.dataset.x === 'wd' ? 'వైడ్ మీద అదనంగా ఎన్ని పరుగులు?' : 'నో బాల్ మీద ఎన్ని పరుగులు కొట్టారు?', ['0', '1', '2', '3', '4', '6']);
    if (i < 0) return;
    return App.my.ball({ r: [0, 1, 2, 3, 4, 6][i], w: false, x: el.dataset.x });
  }
  return App.my.ball({ r: Number(el.dataset.r) || 0, w: false, x: '' });
});
App.click('#sc-undo', async () => {
  const m = App.my.m();
  if (!m) return;
  if (m.done) {
    if (!(await App.ask('మ్యాచ్ అయిపోయింది. చివరి బంతి వెనక్కి తీసుకోవాలా?', 'వెనక్కి', 'వద్దు'))) return;
    m.done = false;
    for (const h of App.items('history').filter((x) => x.mid === m.id)) App.del('history', h.id);
  }
  if (m.cur === 1 && !m.inn[1].balls.length) m.cur = 0;
  const b = m.inn[m.cur].balls.pop();
  if (!b) { App.toast('వెనక్కి తీసుకోవడానికి బంతి లేదు'); return; }
  App.my.setM(m);
  App.toast('చివరి బంతి (' + App.my.ballText(b) + ') తీసేశాను');
  App.refresh();
});
App.click('#sc-say', async () => { const m = App.my.m(); if (!m) return; try { await App.say(App.my.line(m)); } catch (e) { App.toast('చదవలేకపోయాను'); } });
App.click('#sc-share', async () => { const m = App.my.m(); if (!m) return; try { await App.share('🏏 ' + m.a + ' vs ' + m.b + '\n' + App.my.full(m)); } catch (e) { App.toast('షేర్ కాలేదు'); } });
App.click('#sc-close', () => { App.awake(false).catch(() => {}); App.back(); });

App.onShow('history', () => {
  App.awake(false).catch(() => {});
  const h = App.items('history').slice().sort((a, b) => b.at - a.at);
  App.set('#hist-list', h.length ? '<div class="list">' + h.map((x) => `
    <div class="item" data-id="${App.esc(x.id)}"><div class="ic">🏆</div>
      <div class="w"><div class="t">${App.esc(x.a)} vs ${App.esc(x.b)}</div><div class="s">${App.esc(x.result)}</div>
        <div class="s">${App.date(x.date, 'short')} · ${App.esc(x.line1)} · ${App.esc(x.line2)}</div></div></div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">📜</div>అయిపోయిన మ్యాచ్‌లు ఇక్కడ ఉంటాయి.</div>');
});
App.click('#hist-list .item', async (ev, el) => {
  const x = App.find('history', el.dataset.id);
  if (!x) return;
  const i = await App.pick(x.a + ' vs ' + x.b, ['📤 షేర్', '🗑️ తీసేయి']);
  if (i === 0) { try { await App.share('🏏 ' + x.a + ' vs ' + x.b + '\n' + x.line1 + '\n' + x.line2 + '\n🏆 ' + x.result); } catch (e) { App.toast('షేర్ కాలేదు'); } }
  if (i === 1 && await App.ask('ఈ మ్యాచ్ తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del('history', x.id); App.refresh(); }
});
